-- =================================================================
-- MakeIt // HQ — øvelsesbibliotek-udvidelse (369 MoveKit-øvelser, batch 2026-10)
-- =================================================================
-- AI-genereret coaching-data (draft) fra MoveKit-biblioteket. ALLE
-- importeres med is_published=false — Munk reviewer og publicerer i
-- batches via coach-fladerne. demo_asset_url sættes separat ved
-- video-ingestion. Muskel-highlighting + cues virker uden video.
--
-- Idempotent: upsert on slug. Genereret af scripts/gen-exercise-seed.mjs.

insert into public.exercises (
  slug, name, category, pattern, equipment, difficulty,
  primary_muscle, primary_muscles, secondary_muscles, tertiary_muscles,
  cue, cues, mistakes,
  why_matters, setup, progression, regression,
  display_order, is_published
) values
  ('90-90-hip-switches', '90/90 Hip Switches', 'mobility', 'mobility', 'bodyweight', 'beginner',
   'Hips', '{glutes,adductors}', '{abs,obliques}', '{lower_back,hamstrings}',
   'Sid højt, lad knæene falde fra side til side, og roter fra hoften, ikke fra lænden.', $ex$["Sid med begge knæ bøjet 90 grader, det ene ben foran og det andet ud til siden.","Rejs brystet og hold ryggen lang gennem hele skiftet.","Løft knæene og drej dem over til modsatte side med hælene plantet i gulvet.","Lad begge knæ lande roligt i gulvet, før du skifter tilbage.","Pust ud i yderpositionen og træk vejret ind under skiftet."]$ex$, $ex$[{"title":"Ryggen falder sammen","body":"Du runder lænden og læner dig bagud, så hoften slipper for at rotere. Sid højt på siddeknoglerne og støt let med hænderne bag dig, hvis det er nødvendigt."},{"title":"Hælene flytter sig","body":"Glider fødderne rundt, forsvinder rotationen i hoften. Plant hælene og brug dem som omdrejningspunkt."},{"title":"For hurtige skift","body":"Fart skjuler de stive punkter. Brug to til tre sekunder pr. skift og stop kort i hver yderposition."}]$ex$,
   'Træner både indad- og udadrotation i hoften, som typisk mangler efter mange timer siddende. Giver bedre dybde og knæsporing i squat og lunges.', 'Sid på gulvet med fødderne lidt bredere end hoftebredde og knæene bøjet. Lad begge knæ falde til samme side, så begge ben danner cirka 90 grader. Hænderne i gulvet bag dig eller samlet foran brystet.', 'Lav skiftet uden hænder i gulvet, eller læn overkroppen frem over det forreste skinneben i hver yderposition.', 'Støt med begge hænder bag dig og gør udslaget mindre, eller sid på en yogablok eller pude for at hæve hoften.',
   995, false),
  ('adductor-groin-stretch', 'Adductor Groin Stretch', 'mobility', 'mobility', 'bodyweight', 'beginner',
   'Adductors', '{adductors}', '{hamstrings,glutes}', '{lower_back,abs}',
   'Stå bredt, skub hoften bagud og til siden, og hold det strakte ben langt.', $ex$["Stå med fødderne cirka dobbelt skulderbredde og tæerne lige frem.","Bøj det ene knæ og skub hoften bagud, mens det andet ben forbliver strakt.","Hold hele foden på det strakte ben i gulvet.","Hold ryggen lang og brystet åbent, med hænderne på låret eller i gulvet.","Træk vejret roligt og synk lidt dybere på hver udånding.","Hold 20 til 30 sekunder og skift side."]$ex$, $ex$[{"title":"Du gynger i strækket","body":"Små ryk får musklen til at spænde imod. Find positionen, hold den stille i 20 til 30 sekunder, og lad åndedrættet gøre arbejdet."},{"title":"Ryggen runder","body":"Når lænden krummer, flytter strækket væk fra inderlåret. Skub hoften bagud og hold brystet fremme."},{"title":"Knæet falder ind","body":"Det bøjede knæ skal pege samme vej som tæerne. Pres det let udad og hold vægten på hele foden."}]$ex$,
   'Løsner inderlår og lyske, som ofte begrænser dybden i squat og sidelæns bevægelser. Særligt relevant for løbere og boldspillere, hvor lysken tager mange retningsskift.', 'Stå bredt med tæerne pegende lige frem eller let udad. Hænderne på hofterne eller foran kroppen. Fordel vægten jævnt, før du skifter over på den ene side.', 'Gå dybere ned mod en cossack squat-position, eller skift til frog stretch på alle fire for større bevægeudslag.', 'Gør standen smallere og udslaget mindre, eller lav strækket siddende med fodsålerne samlet (butterfly).',
   1035, false),
  ('alternating-hammer-curl', 'Alternating Hammer Curl', 'arms', 'isolation', 'dumbbell', 'beginner',
   'Biceps/Forearms', '{biceps,forearms}', '{front_delts}', '{abs,traps}',
   'Tommelfingrene op, albuerne låst ved siden, én arm ad gangen uden sving.', $ex$["Hold håndvægtene med neutralt greb, håndfladerne mod hinanden.","Lås albuerne ind til siden og lad dem blive der.","Curl den ene vægt op mod skulderen uden at dreje håndleddet.","Sænk kontrolleret til strakt arm, før den anden arm starter.","Spænd mave og baller, så overkroppen står stille."]$ex$, $ex$[{"title":"Sving med overkroppen","body":"Du læner dig tilbage og bruger hoften til at kaste vægten op. Gå ned i vægt og hold ribbenene nede over bækkenet."},{"title":"Albuen vandrer frem","body":"Når albuen flytter sig frem, overtager forreste skulder. Hold overarmen lodret gennem hele bevægelsen."},{"title":"Halve gentagelser","body":"Du stopper, før armen er strakt, og mister arbejdet i bunden. Stræk helt ud i hver gentagelse."}]$ex$,
   'Det neutrale greb rammer brachialis og brachioradialis, som giver tykkelse til overarmen og styrke til underarmen. Styrker greb og albuebøjning til rows og pull-ups.', 'Stå hoftebredt med en håndvægt i hver hånd og armene strakt langs siden. Håndfladerne vender ind mod kroppen. Skuldrene nede og tilbage.', 'Tilføj tre sekunders sænkefase, eller gå op i vægt, når alle gentagelser er uden sving.', 'Lav øvelsen siddende med ryglæn, eller brug lettere vægte og curl begge arme samtidig.',
   1035, false),
  ('arc-trainer', 'Arc Trainer', 'cardio', 'conditioning', 'cardio-machine', 'beginner',
   'Quads/Glutes', '{quads,glutes}', '{hamstrings,calves_back}', '{abs,lower_back}',
   'Oprejst overkrop, tryk gennem hele foden, og hold en jævn kadence.', $ex$["Stå oprejst med brystet fremme og blikket lige frem.","Tryk ned gennem hele foden, ikke kun forfoden.","Hold en jævn kadence og lad modstanden styre intensiteten.","Hold let om håndtagene, så benene laver arbejdet.","Træk vejret rytmisk, og sænk tempoet, hvis du mister rytmen."]$ex$, $ex$[{"title":"Du hænger i håndtagene","body":"Læner du dig tungt på armene, falder belastningen på benene, og pulsen bliver misvisende. Hold kun let for balancens skyld."},{"title":"Lav modstand og høj fart","body":"Benene spinner uden reelt arbejde. Skru modstanden op, til du kan mærke hvert tryk."},{"title":"Foroverbøjet holdning","body":"Rund ryg lukker for vejrtrækningen og belaster lænden. Rejs brystet og hold hoften over fødderne."}]$ex$,
   'Giver kredsløbstræning med lav belastning på knæ og hofter, fordi fødderne aldrig slipper pedalerne. Et godt alternativ til løb i perioder med mange kilometer eller ømme led.', 'Stil dig på pedalerne med hele foden i kontakt. Vælg en lav til moderat hældning og en modstand, du kan holde i rolig rytme. Tag fat i de bevægelige håndtag eller de faste greb.', 'Øg modstand eller hældning, forlæng varigheden, eller kør intervaller, fx 1 minut hårdt og 1 minut roligt.', 'Sænk modstand og hældning, og kør kortere pas på 10 til 15 minutter i samtaletempo.',
   1035, false),
  ('archer-push-up', 'Archer Push-Up', 'upper-body-push', 'push-horizontal', 'bodyweight', 'advanced',
   'Chest', '{chest,triceps,front_delts}', '{abs,obliques}', '{glutes,quads}',
   'Læg vægten over på den ene arm, og lad den anden glide strakt ud til siden.', $ex$["Sæt hænderne bredt, cirka dobbelt skulderbredde, med fingrene let udad.","Sænk brystet ned mod den ene hånd, mens den anden arm strækkes.","Hold albuen på arbejdsarmen cirka 45 grader fra kroppen.","Spænd mave og baller, så kroppen er en lige linje.","Pres op gennem arbejdsarmen og brug kun støttearmen til balance."]$ex$, $ex$[{"title":"Hoften roterer","body":"Kroppen drejer mod arbejdsarmen for at gøre det lettere. Hold hoften parallel med gulvet og spænd ballerne."},{"title":"Støttearmen laver arbejdet","body":"Bøjer du støttearmen, bliver det en bred armbøjning. Hold den strakt og læg bevidst vægten over på arbejdssiden."},{"title":"Hoften hænger","body":"Lænden svajer, og spændingen forsvinder fra core. Træk ribbenene ned og hold bækkenet neutralt."}]$ex$,
   'Flytter størstedelen af kropsvægten over på én arm og bygger ensidig pressestyrke uden udstyr. Et naturligt trin på vejen mod one-arm push-up.', 'Start i høj plankeposition med hænderne markant bredere end skuldrene. Fødderne i hoftebredde eller lidt bredere for balance. Kroppen i en lige linje fra hoved til hæl.', 'Smallere fodstilling, pause i bunden, eller støttearmen kun på fingerspidserne som vej mod one-arm push-up.', 'Lav bevægelsen med knæene i gulvet eller hænderne på en bænk, eller start med brede armbøjninger.',
   1035, false),
  ('arm-circles-front-back', 'Arm Circles (Front and Back)', 'mobility', 'mobility', 'bodyweight', 'beginner',
   'Shoulders', '{front_delts,rear_delts}', '{traps,chest}', '{lats,abs}',
   'Store, rolige cirkler fra skulderen, først fremad, så bagud.', $ex$["Stå oprejst med ribbenene nede og maven let spændt.","Start med små cirkler og gør dem gradvist større.","Stræk armene og tegn så store cirkler, du kan, uden at svaje i lænden.","Lav 10 til 15 cirkler fremad, og skift så retning.","Træk vejret roligt og hold nakken afspændt."]$ex$, $ex$[{"title":"Svaj i lænden","body":"Når armene passerer over hovedet, skyder ribbenene frem for at kompensere for stive skuldre. Spænd maven let og gør cirklen mindre."},{"title":"Skuldrene trækkes op mod ørerne","body":"Nakken overtager, og skulderleddet bevæger sig mindre. Sænk skuldrene og lad armen rotere frit."},{"title":"For hurtigt tempo","body":"Kast med armene giver ingen kontrol i yderstillingerne. Hold et tempo, hvor du kan styre hele cirklen."}]$ex$,
   'Varmer skulderleddet og musklerne omkring det op før pres og træk. En enkel drill, der hurtigt viser, om skuldrene er klar til overhead-arbejde.', 'Stå med fødderne i hoftebredde og armene strakt ned langs siden. Blikket lige frem og vægten midt på foden.', 'Lav cirklerne med én arm ad gangen i langsomt tempo for fuld kontrol, eller gør cirklerne større og forlæng til 20 gentagelser hver vej.', 'Lav små cirkler med armene ud til siden i skulderhøjde, eller bøj albuerne og cirkl med hænderne på skuldrene.',
   1035, false),
  ('arnold-press', 'Arnold Press', 'shoulders', 'push-vertical', 'dumbbell', 'intermediate',
   'Shoulders', '{front_delts,triceps}', '{traps,chest}', '{abs,rear_delts,lower_back}',
   'Start med håndfladerne mod dig, roter ud undervejs, og pres til strakte arme over hovedet.', $ex$["Start med håndvægtene foran skuldrene og håndfladerne mod dig.","Drej albuerne ud til siden, mens du presser op.","Afslut med håndfladerne fremad og armene strakte over skuldrene.","Sænk samme vej tilbage og roter ind til startpositionen.","Hold ribbenene nede og maven spændt hele vejen."]$ex$, $ex$[{"title":"Rotation og pres deles op","body":"Du drejer først og presser bagefter, så det bliver to bevægelser. Lad rotationen ske flydende gennem hele presset."},{"title":"Svaj i lænden","body":"Vægtene er for tunge, og ribbenene skyder frem. Gå ned i vægt, spænd baller og mave, eller sid med ryglæn."},{"title":"Kort bevægebane","body":"Du stopper før strakte arme eller sænker ikke helt ned foran skuldrene. Brug hele banen i hver gentagelse."}]$ex$,
   'Rotationen giver længere bevægebane og mere tid under spænding for skulderen end et almindeligt skulderpres. Bygger skuldre og træner kontrol gennem hele presset.', 'Sid på en bænk med ryglænet næsten lodret, eller stå hoftebredt. Løft håndvægtene til skulderhøjde med håndfladerne mod dig og albuerne foran kroppen. Fødderne plantet og maven spændt.', 'Lav øvelsen stående for større krav til core, eller tilføj tre sekunders sænkefase.', 'Almindeligt siddende dumbbell shoulder press uden rotation, eller lettere vægte med ryglæn.',
   1035, false),
  ('assault-bike', 'Assault Bike', 'cardio', 'conditioning', 'cardio-machine', 'beginner',
   'Quads/Glutes', '{quads,glutes}', '{hamstrings,calves_back,lats,triceps}', '{abs,chest,front_delts,biceps}',
   'Skub og træk med armene i takt med benene, og hold overkroppen rolig.', $ex$["Sid oprejst med let foroverlæn og spændt mave.","Skub og træk aktivt i håndtagene i takt med pedalerne.","Tryk gennem forfoden og hold en jævn rytme.","Start kontrolleret. Modstanden stiger med farten.","Træk vejret dybt og rytmisk, også når intensiteten stiger.","Styr efter watt eller omdrejninger, ikke efter følelsen i de første sekunder."]$ex$, $ex$[{"title":"For hård start","body":"Modstanden stiger kraftigt med farten, så en vild åbning koster resten af intervallet. Ram dit måltempo fra start og hold det."},{"title":"Kun benene arbejder","body":"Armene hænger bare med, og du mister en stor del af effekten. Skub og træk bevidst i håndtagene."},{"title":"Overkroppen vugger","body":"Du kaster kroppen fra side til side og spilder energi. Hold hoften stille på sædet og lad arme og ben lave arbejdet."}]$ex$,
   'Bruger arme og ben samtidig og driver pulsen hurtigt op uden stødbelastning. Velegnet til korte intervaller og konditionsarbejde, når benene skal skånes for løb.', 'Indstil sadlen, så knæet er let bøjet, når pedalen er i bund. Sæt fødderne fast på pedalerne og tag fat i begge håndtag. Sid oprejst, før du starter.', 'Forlæng intervallerne, forkort pauserne, eller kør efter et fast wattmål, fx 10 x 30 sekunder hårdt med 30 sekunders pause.', 'Kør i roligt, jævnt tempo i 5 til 10 minutter, eller forlæng pauserne mellem intervallerne.',
   1035, false),
  ('assisted-pistol-squat', 'Assisted Pistol Squat', 'lower-body', 'squat', 'bodyweight', 'intermediate',
   'Quads', '{quads,glutes}', '{hamstrings,adductors}', '{abs,calves_back,lower_back}',
   'Hold let i støtten, sid ned på ét ben, og lad benet lave arbejdet.', $ex$["Hold let i en stolpe eller et rack med armene næsten strakte.","Stræk det frie ben frem og hold det fri af gulvet.","Sæt hoften tilbage og ned, og lad knæet følge tæerne.","Hold hælen i gulvet hele vejen ned og op.","Pres op gennem hele foden og brug armene så lidt som muligt."]$ex$, $ex$[{"title":"Armene trækker dig op","body":"Støtten bliver til en row, og benet slipper for arbejdet. Hold kun med fingerspidserne og brug hænderne til balance."},{"title":"Hælen løfter sig","body":"Vægten ryger frem på tæerne, og knæet belastes unødigt. Hold trykket på hele foden, og gå kun så dybt, som anklen tillader."},{"title":"Knæet falder ind","body":"Standbenets knæ kollapser indad i bunden. Pres knæet ud over lilletåen og hold hoften vandret."}]$ex$,
   'Bygger ensidig benstyrke, balance og ankelmobilitet og afslører forskelle mellem højre og venstre ben. Støtten gør det muligt at træne fuld dybde, før styrken er der til en fri pistol squat.', 'Stå på ét ben foran en stolpe, et rack eller en dørkarm, og hold fat i hoftehøjde. Standfoden peger lige frem med vægten midt på foden. Løft det andet ben strakt frem.', 'Brug mindre støtte (én hånd, derefter fingerspidser), sænk over fem sekunder, og gå videre til fri pistol squat.', 'Sæt dig ned på en kasse eller bænk på ét ben og rejs dig igen, eller hold fast i en TRX for mere hjælp.',
   1035, false),
  ('b-stance-hip-thrust', 'B-Stance Hip Thrust', 'lower-body', 'hinge', 'barbell', 'intermediate',
   'Glutes', '{glutes}', '{hamstrings,quads}', '{abs,adductors,lower_back}',
   'Pres gennem hælen på arbejdsbenet, og lås hoften ud med hagen nede.', $ex$["Sæt arbejdsfoden fladt i gulvet og støttefodens hæl ud for arbejdsfodens tæer.","Læg cirka 80 procent af vægten på arbejdsbenet.","Pres hoften op, til overkrop og lår danner en lige linje.","Hold hagen nede og ribbenene trukket ned, så bækkenet tipper let bagud i toppen.","Klem ballen et sekund i toppen og sænk kontrolleret."]$ex$, $ex$[{"title":"Støttebenet tager over","body":"Presser du lige meget med begge ben, er det en almindelig hip thrust. Støttefoden hviler kun på hælen og holder balancen."},{"title":"Svaj i lænden i toppen","body":"Du løfter højere ved at overstrække ryggen i stedet for hoften. Hold hage og ribben nede, og stop når hoften er strakt."},{"title":"Hoften drejer","body":"Bækkenet tipper mod støttebenet under løftet. Hold begge hoftekamme i samme højde, og gå ned i vægt, hvis du ikke kan."}]$ex$,
   'Lægger det meste af belastningen på én balle ad gangen, men med mere stabilitet end en ren etbens hip thrust. Udligner sideforskelle og tillader tungere vægt i ensidigt glute-arbejde.', 'Sid med øvre ryg (lige under skulderbladene) mod en bænk og stangen over hoftebøjningen med en pude imellem. Arbejdsfoden fladt i gulvet, så skinnebenet er lodret i toppen. Støttefoden lidt længere fremme, kun med hælen i gulvet.', 'Etbens hip thrust med det frie ben løftet, eller tilføj to sekunders pause i toppen.', 'Almindelig hip thrust på to ben, eller B-stance glute bridge fra gulvet med kropsvægt.',
   1035, false),
  ('back-extension', 'Back Extension', 'lower-body', 'hinge', 'bodyweight', 'beginner',
   'Lower Back/Glutes', '{lower_back,glutes}', '{hamstrings,adductors}', '{abs,obliques}',
   'Bøj i hoften med lang ryg, og løft til kroppen er én lige linje.', $ex$["Stil puden lige under hoftebenet, så hoften kan bøje frit.","Sænk overkroppen kontrolleret med neutral ryg.","Spænd ballerne og løft, til kroppen danner en lige linje fra hæl til hoved.","Stop i neutral. Læn dig ikke bagover i toppen.","Hold hagen let ind og blikket mod gulvet."]$ex$, $ex$[{"title":"Overstræk i toppen","body":"Lænden svajer hårdt for at komme højere op, og trykket lander i lænden. Stop når krop og ben er på linje, og afslut med ballerne."},{"title":"Puden sidder for højt","body":"Hoften bliver låst, så bevægelsen kommer fra at runde og strække lænden. Sænk puden til lige under hoftebenet."},{"title":"Sving og fart","body":"Kroppen kastes op med momentum. Brug to sekunder ned, hold en kort pause, og løft roligt."}]$ex$,
   'Styrker lænd, baller og baglår uden tung belastning på rygsøjlen. Giver en bagkæde, der holder i dødløft, squat og hverdag.', 'Indstil 45-graders rygbænken, så puden sidder lige under hoftebenet. Hælene fast mod fodpladen, armene krydset over brystet, kroppen i lige linje.', 'Hold en vægtskive eller håndvægt mod brystet, eller tilføj tre sekunders pause i toppen.', 'Forkort bevægelsen på bænken, eller lav øvelsen liggende på maven på gulvet (superman).',
   1035, false),
  ('backpack-curls', 'Backpack Curls', 'arms', 'isolation', 'bodyweight', 'beginner',
   'Biceps', '{biceps}', '{forearms}', '{front_delts,abs}',
   'Albuerne låst ved siden, curl rygsækken op og sænk den langsomt.', $ex$["Tag fat i hanken med begge hænder, eller hold én strop i hver hånd.","Hold albuerne ind til kroppen gennem hele bevægelsen.","Curl op, til underarmene er forbi vandret, og klem biceps i toppen.","Sænk på tre sekunder, til armene er næsten strakte.","Stå rank med spændt mave. Ingen gyngen fra hoften."]$ex$, $ex$[{"title":"Kroppen gynger med","body":"Hoften skubber vægten op, og biceps slipper for arbejdet. Stå med ryggen mod en væg, eller tag vægt ud af rygsækken."},{"title":"Albuerne vandrer frem","body":"Skulderen overtager, og spændingen forsvinder i toppen. Hold albuerne ved ribbenene."},{"title":"Halve gentagelser","body":"Rygsækken sænkes kun halvt ned. Stræk armene næsten helt ud i bunden på hver gentagelse."}]$ex$,
   'Giver reel bicepstræning derhjemme uden håndvægte. Belastningen justeres let ved at pakke rygsækken tungere eller lettere.', 'Pak rygsækken med bøger eller vandflasker, og luk den stramt, så indholdet ikke skrider. Stå med fødderne i hoftebredde og rygsækken hængende foran lårene i strakte arme.', 'Pak rygsækken tungere, sænk på fem sekunder, eller curl med én arm ad gangen.', 'Tag vægt ud af rygsækken, eller stå med ryggen mod en væg for støtte.',
   1035, false),
  ('backpack-row', 'Backpack Row', 'upper-body-pull', 'pull-horizontal', 'bodyweight', 'beginner',
   'Back', '{lats,traps}', '{rear_delts,biceps}', '{forearms,lower_back,hamstrings,abs}',
   'Flad ryg, træk rygsækken mod navlen og klem skulderbladene sammen.', $ex$["Bøj frem i hoften med flad ryg og let bøjede knæ.","Træk albuerne bagud langs kroppen, mod hoften.","Klem skulderbladene sammen i toppen og hold et sekund.","Sænk kontrolleret til strakte arme uden at runde ryggen.","Hold nakken lang og blikket skråt ned."]$ex$, $ex$[{"title":"Ryggen runder","body":"Lænden bærer belastningen i en svag position. Skub hoften bagud, spænd maven og hold brystet frem."},{"title":"Overkroppen rejser sig","body":"Hvert træk bliver til et ryk med hele kroppen. Hold vinklen i hoften fast, og gør rygsækken lettere."},{"title":"Skuldrene trækkes op mod ørerne","body":"Øvre traps overtager fra lats og midterryg. Træk skuldrene ned og albuerne mod hoften."}]$ex$,
   'Træner ryggens træk derhjemme og opvejer mange timers siddende arbejde. En stærk øvre ryg giver bedre holdning og sundere skuldre.', 'Pak rygsækken tungt og luk den stramt. Stå med fødderne i hoftebredde, grib hanken eller begge stropper, og bøj frem i hoften med flad ryg og strakte arme.', 'Pak tungere, hold to sekunders pause i toppen, eller ro med én arm ad gangen.', 'Støt den frie hånd på en stol og ro med én arm, eller gør rygsækken lettere.',
   1035, false),
  ('backstroke-swim', 'Backstroke Swim', 'cardio', 'conditioning', 'bodyweight', 'intermediate',
   'Back/Shoulders', '{lats,rear_delts}', '{triceps,traps,glutes,quads}', '{abs,obliques,hamstrings}',
   'Lig højt i vandet, rul fra skulder til skulder, og hold et jævnt benspark.', $ex$["Hold hovedet stille med ørerne i vandet og blikket lige op.","Pres hoften op mod overfladen, så kroppen ligger vandret.","Sæt lillefingeren først i vandet, i forlængelse af skulderen.","Rul kroppen fra skulder til skulder med hvert armtag.","Spark småt og hurtigt fra hoften med løse ankler.","Træk vejret i en fast rytme: ind på den ene arm, ud på den anden."]$ex$, $ex$[{"title":"Hoften synker","body":"Kroppen sidder i vandet, og modstanden stiger kraftigt. Læg hovedet tilbage, spænd let i maven og pres hoften op."},{"title":"Sparket kommer fra knæene","body":"Knæene bryder overfladen, og fremdriften forsvinder. Spark fra hoften med næsten strakte ben, så kun tæerne bryder vandet."},{"title":"Armen krydser midterlinjen","body":"Hånden sættes i bag hovedet, og kroppen slingrer. Sæt i ud for skulderen, cirka klokken 11 og klokken 1."}]$ex$,
   'Skånsom kondition, der styrker ryg og skuldre og åbner brystet. Et godt modspil til crawl og til en hverdag foran skærmen.', 'Skub fra bassinkanten på ryggen med armene strakt over hovedet. Find vandret leje, start bensparket, og begynd armtagene skiftevis.', 'Svøm længere intervaller, kort pauserne ned, eller læg fartskift ind: 25 meter hurtigt, 25 meter roligt.', 'Svøm kun rygbenspark med armene langs siden eller en svømmeplade holdt over lårene, og hold pause ved hver bassinlængde.',
   1035, false),
  ('band-assisted-pull-up', 'Band-Assisted Pull-Up', 'upper-body-pull', 'pull-vertical', 'band', 'beginner',
   'Lats', '{lats,biceps}', '{traps,rear_delts,forearms}', '{abs}',
   'Skuldrene ned, træk brystet mod stangen, og sænk dig roligt helt ud.', $ex$["Start i dødt hæng med strakte arme og spændt mave.","Træk skulderbladene ned og tilbage, før albuerne bøjer.","Træk albuerne ned mod hoften, til hagen er over stangen.","Sænk dig på to til tre sekunder til helt strakte arme.","Hold benene samlet og kroppen stiv, så elastikken ikke svinger dig."]$ex$, $ex$[{"title":"Elastikken gør arbejdet","body":"Du hopper op af bunden på elastikkens rekyl. Start hver gentagelse fra stille hæng, og skift til en tyndere elastik, når du kan tage otte rene."},{"title":"Halvt udslag","body":"Armene strækkes ikke i bunden, eller hagen når ikke over stangen. Tag fuld bevægelse i hver gentagelse, også når det koster gentagelser."},{"title":"Skuldrene op i ørerne","body":"Uden aktive skulderblade hænger du i leddet. Træk skuldrene ned først, og hold brystet løftet mod stangen."}]$ex$,
   'Lader dig træne hele pull-up-bevægelsen, før du kan løfte din egen kropsvægt. Bygger lats og greb i præcis det mønster, du skal mestre.', 'Bind en lang træningselastik om stangen, og træk den ned. Sæt en fod eller et knæ i løkken, grib stangen lidt bredere end skulderbredde med overhåndsgreb, og hæng i strakte arme.', 'Skift til en tyndere elastik, eller lav langsomme negative pull-ups uden elastik.', 'Brug en tykkere elastik, eller træn inverted rows, til styrken er der.',
   1035, false),
  ('band-external-rotation', 'Band External Rotation', 'shoulders', 'isolation', 'band', 'beginner',
   'Rotator Cuff', '{rear_delts}', '{traps}', '{forearms}',
   'Albuen fast ved siden, drej underarmen udad uden at dreje kroppen.', $ex$["Hold albuen bøjet 90 grader og klemt ind mod siden.","Drej underarmen udad, så langt skulderen tillader, uden at kroppen følger med.","Hold skulderbladet trukket let tilbage og ned.","Før langsomt tilbage på tre sekunder. Lad ikke elastikken trække dig.","Hold håndleddet lige og neutralt."]$ex$, $ex$[{"title":"Albuen slipper siden","body":"Bevægelsen bliver til et løft med skulderen i stedet for en rotation. Klem et sammenrullet håndklæde mellem albue og krop."},{"title":"Overkroppen drejer med","body":"Du snyder dig til udslag med hele torsoen. Stå stille med hofte og bryst lige frem, og brug en lettere elastik."},{"title":"For hård elastik","body":"Rotatorcuffen består af små muskler. Vælg en modstand, du kan styre i 15 rene gentagelser."}]$ex$,
   'Styrker rotatorcuffen, som holder skulderleddet centreret under pres og træk. Billig forsikring for skuldre, der skal holde til bænkpres og overhead-arbejde.', 'Fastgør elastikken i albuehøjde. Stå med siden til ankeret, grib elastikken med den yderste hånd, albuen bøjet 90 grader ind mod kroppen og underarmen hen over maven.', 'Lav øvelsen med albuen løftet 90 grader ud til siden, eller brug en hårdere elastik.', 'Brug en lettere elastik, stil dig tættere på ankeret, eller lav rotationen liggende på siden uden modstand.',
   1045, false),
  ('band-glute-bridge', 'Band Glute Bridge', 'lower-body', 'hinge', 'band', 'beginner',
   'Glutes', '{glutes}', '{hamstrings}', '{abs,lower_back}',
   'Pres knæene ud mod elastikken, og løft hoften med ballerne.', $ex$["Pres knæene ud mod elastikken hele vejen, så de står over fødderne.","Vip bækkenet let bagover og spænd maven, før du løfter.","Tryk hælene i gulvet og løft hoften, til krop og lår er på linje.","Klem ballerne hårdt i toppen i et sekund.","Sænk kontrolleret uden at slippe presset mod elastikken."]$ex$, $ex$[{"title":"Lænden svajer i toppen","body":"Hoften presses for højt, og lænden overtager. Stop når skuldre, hofte og knæ er på linje, og hold ribbenene nede."},{"title":"Knæene falder ind","body":"Elastikken vinder, og ballernes yderside slipper. Pres aktivt udad gennem hele gentagelsen, eller brug en lettere elastik."},{"title":"Baglårene tager over","body":"Fødderne står for langt fremme, så du får krampe i baglåret. Flyt hælene tættere på ballerne, så skinnebenene er lodrette i toppen."}]$ex$,
   'Aktiverer og styrker ballerne med minimal belastning på ryggen. Elastikken sætter også ballernes yderside på arbejde, så knæene sporer bedre i squat og løb.', 'Sæt en minielastik lige over knæene. Lig på ryggen med bøjede knæ, fødderne i hoftebredde tæt på ballerne og armene langs siden.', 'Lav øvelsen på ét ben, hæv skuldrene op på en bænk til hip thrust, eller læg vægt på hoften.', 'Lav broen uden elastik, eller forkort bevægelsen til det udslag, du kan styre.',
   1045, false),
  ('band-good-morning', 'Band Good Morning', 'lower-body', 'hinge', 'band', 'beginner',
   'Hams/Glutes', '{hamstrings,glutes}', '{lower_back,adductors}', '{abs,traps}',
   'Skub hoften bagud med flad ryg, og rejs dig ved at spænde ballerne.', $ex$["Læg elastikken over øvre traps, ikke på nakkehvirvlerne, og hold fast i den med hænderne.","Bøj let i knæene og hold den vinkel.","Skub hoften langt bagud, til du mærker stræk i baglårene.","Hold ryggen flad og brystet frem hele vejen.","Driv hoften frem og spænd ballerne i toppen."]$ex$, $ex$[{"title":"Ryggen runder","body":"Du går dybere, end baglårene tillader, og lænden giver efter. Stop når hoften ikke kan komme længere bagud."},{"title":"Det bliver til en squat","body":"Knæene bøjer mere og mere, og baglårene slipper. Hold knævinklen fast og tænk hoften bagud, ikke ned."},{"title":"Elastikken ligger på nakken","body":"Trykket lander på halshvirvlerne. Læg den over øvre traps og hold den på plads med hænderne ved skuldrene."}]$ex$,
   'Lærer hoftebøjningen, som dødløft og kettlebell swing bygger på, med lav belastning. Elastikken giver mest modstand i toppen, hvor ballerne skal låse ud.', 'Stå på en lang træningselastik med fødderne i hoftebredde. Før den anden ende over hovedet, og læg den over øvre traps. Hold i elastikken ved skuldrene, og rejs dig til strakt hofte.', 'Brug en tykkere elastik, sænk på fire sekunder, eller skift til good morning med stang.', 'Lav bevægelsen uden elastik med hænderne på hoften, eller øv hoftebøjningen med ballerne mod en væg.',
   1045, false),
  ('band-leg-curl', 'Band Leg Curl', 'lower-body', 'isolation', 'band', 'beginner',
   'Hamstrings', '{hamstrings}', '{calves_back}', '{glutes,lower_back}',
   'Hoften i gulvet, træk hælen mod ballen, og sænk langsomt.', $ex$["Pres hoften ned i gulvet og spænd let i ballerne.","Træk hælen mod ballen i en jævn bue.","Klem baglåret i toppen i et sekund.","Stræk benet ud på tre sekunder mod elastikkens træk.","Hold tæerne trukket op mod skinnebenet, så elastikken bliver siddende."]$ex$, $ex$[{"title":"Hoften løfter sig","body":"Lænden svajer, og bevægelsen flytter væk fra baglåret. Pres hoftebenene ned i underlaget, og brug en lettere elastik."},{"title":"Elastikken smækker benet tilbage","body":"Den excentriske fase er halvdelen af træningen. Brems hele vejen ud til strakt ben."},{"title":"For lidt spænding fra start","body":"Ligger du for tæt på ankeret, er elastikken slap i bunden. Ryk væk, til der er træk allerede med strakte ben."}]$ex$,
   'Træner baglårets knæbøjning, som hinge-øvelser ikke rammer fuldt. Stærke baglår beskytter knæet og mindsker risikoen for fiberskader ved sprint.', 'Fastgør elastikken lavt i et solidt ankerpunkt, og sæt løkken om anklerne eller én ankel. Lig på maven med fødderne mod ankeret, benene strakte og så langt væk, at elastikken er spændt.', 'Curl ét ben ad gangen, brug en tykkere elastik, eller ryk længere væk fra ankeret.', 'Brug en tyndere elastik, lig tættere på ankeret, eller lav bevægelsen stående med støtte fra en væg.',
   1085, false),
  ('band-overhead-press', 'Band Overhead Press', 'shoulders', 'push-vertical', 'band', 'beginner',
   'Shoulders', '{front_delts,triceps}', '{traps,chest}', '{abs,obliques,lower_back}',
   'Spænd mave og baller, pres lige op, og lås ud med overarmene ved ørerne.', $ex$["Start med hænderne i skulderhøjde og underarmene lodrette.","Spænd mave og baller, så ribbenene bliver nede.","Pres lige op, til armene er strakte og overarmene er ud for ørerne.","Sænk kontrolleret til skulderhøjde. Lad ikke elastikken trække dig ned.","Hold håndleddene lige over albuerne."]$ex$, $ex$[{"title":"Svaj i lænden","body":"Ribbenene flyver op, og lænden tager presset. Klem ballerne, spænd maven, og brug en lettere elastik."},{"title":"Pres fremad i stedet for op","body":"Hænderne ender foran hovedet, og skulderen arbejder i en svag vinkel. Før hovedet let frem i toppen, så armene står lodret."},{"title":"Ingen kontrol på vej ned","body":"Elastikken trækker armene ned i ét ryk. Brug to til tre sekunder ned til skulderhøjde."}]$ex$,
   'Bygger skuldre og triceps uden stang eller håndvægte. Elastikken er skånsom i bunden og tungest i toppen, hvor du er stærkest.', 'Stå midt på en lang træningselastik med fødderne i hoftebredde. Grib enderne eller løkken, og før hænderne op til skuldrene med håndfladerne frem og elastikken bag om underarmene.', 'Brug en tykkere elastik, pres én arm ad gangen, eller hold to sekunders pause i toppen.', 'Brug en tyndere elastik, stil fødderne tættere sammen for mindre spænding, eller pres siddende på en stol.',
   1085, false),
  ('band-pull-through', 'Band Pull Through', 'lower-body', 'hinge', 'band', 'beginner',
   'Glutes/Hams', '{glutes,hamstrings}', '{lower_back}', '{abs,adductors,forearms}',
   'Skub hoften bagud, lad båndet trække hænderne mellem benene, og driv hoften frem med balderne.', $ex$["Stå med ryggen til ankeret og hold båndet med begge hænder mellem benene.","Skub hoften langt bagud med let bøjede knæ og neutral ryg.","Lad armene hænge som reb. Hoften laver arbejdet, ikke skuldrene.","Driv hoften frem og klem balderne hårdt i toppen.","Stop, når du står lodret. Læn dig ikke bagover."]$ex$, $ex$[{"title":"Squat i stedet for hoftehængsel","body":"Knæene bøjer for meget, og hoften går ned i stedet for bagud. Hold skinnebenene næsten lodrette og ræk bagdelen bagud mod ankeret."},{"title":"Overstræk i lænden","body":"Du læner dig bagover i toppen og låser med lænden i stedet for balderne. Afslut med ribbenene nede og spændte balder."},{"title":"Armene trækker","body":"Skuldre og arme løfter båndet frem. Hold armene strakte og passive, og lad hoften flytte båndet."}]$ex$,
   'Lærer hoftehængslet med lav belastning på ryggen og giver balderne maksimal spænding i toppen. God som opvarmning til dødløft eller som afslutning for bagkæden.', 'Fastgør båndet lavt bag dig i ankelhøjde. Stå med ryggen til ankeret, fødderne lidt bredere end hoftebredde, og grib båndet mellem benene. Gå frem, til der er træk i båndet i bundpositionen.', 'Brug et tykkere bånd eller gå længere frem, hold to sekunders pause i toppen, eller skift til cable pull through eller kettlebell swing.', 'Brug et lettere bånd og stå tættere på ankeret, eller øv hoftehængslet uden bånd med bagdelen mod en væg.',
   1085, false),
  ('band-shoulder-dislocates', 'Band Shoulder Dislocates', 'mobility', 'mobility', 'band', 'beginner',
   'Shoulders', '{front_delts,chest}', '{rear_delts,traps,lats}', '{forearms,abs}',
   'Strakte arme, bredt greb, før båndet i en rolig bue over hovedet og ned bag ryggen.', $ex$["Tag et bredt greb om båndet med strakte arme foran hoften.","Før båndet op over hovedet og ned bag ryggen i en rolig bue.","Hold albuerne strakte og ribbenene nede hele vejen.","Træk båndet let fra hinanden, når det passerer bag hovedet.","Pust ud på vej bagud, og træk vejret ind på vej frem."]$ex$, $ex$[{"title":"Svaj i lænden","body":"Ribbenene løfter sig for at snyde sig til mere bevægelse. Spænd maven let, og lad kun skuldrene bevæge sig."},{"title":"Bøjede albuer","body":"Albuerne bøjer for at komme forbi det stramme punkt. Tag et bredere greb, så armene kan forblive strakte."},{"title":"For smalt greb og for høj fart","body":"Skulderen tvinges igennem med et ryk. Start bredt, bevæg dig langsomt, og stop ved smerte."}]$ex$,
   'Åbner bryst og skuldre og fører skulderleddet gennem hele bevægebanen. God opvarmning før overhead press, snatch og bænkpres.', 'Stå oprejst med fødderne i hoftebredde. Hold et let bånd foran hoften med overhåndsgreb, markant bredere end skulderbredde. Armene strakte og let spænding i båndet.', 'Flyt hænderne gradvist tættere sammen, eller hold to sekunders pause bag hovedet og i bunden bag ryggen.', 'Tag et bredere greb og brug et lettere bånd, eller stop bevægelsen over hovedet, indtil skuldrene tillader mere.',
   1125, false),
  ('band-squat', 'Band Squat', 'lower-body', 'squat', 'band', 'beginner',
   'Quads', '{quads,glutes}', '{hamstrings,adductors}', '{abs,lower_back,calves_back}',
   'Stå fast på båndet, sid ned mellem hælene, og pres op mod den stigende modstand.', $ex$["Stå midt på båndet med hele foden plantet.","Hold brystet oppe og spænd maven, før du går ned.","Pres knæene ud over tæerne, og sid til hoften er under knæene.","Driv op gennem hele foden, og accelerér mod toppen, hvor båndet er strammest.","Stræk hofte og knæ helt ud uden at svaje i lænden."]$ex$, $ex$[{"title":"Knæene falder ind","body":"Båndets træk afslører svage hofter. Pres knæene aktivt ud mod lilletåen hele vejen op."},{"title":"Halve gentagelser","body":"Båndet er slapt i bunden, så det frister at stoppe højt. Gå i fuld dybde, og sørg for, at båndet er stramt allerede i bunden."},{"title":"Hælene løfter","body":"Vægten ryger frem på tæerne, og brystet falder. Hold trykket på hele foden, og sæt dig ned mellem hælene."}]$ex$,
   'Giver squat-træning uden vægtstang, med stigende modstand mod toppen. Velegnet til hjemmetræning, opvarmning og høje gentagelser.', 'Stå midt på båndet med fødderne i skulderbredde og let udadroterede. Før den anden ende op over skuldrene, eller hold den i hænderne ved kravebenene med albuerne under båndet. Spænd maven, før du går ned.', 'Brug et tykkere bånd eller to bånd, tilføj pause i bunden, eller gå videre til goblet squat eller back squat.', 'Brug et lettere bånd, eller lav bodyweight squat ned til en kasse eller stol.',
   1145, false),
  ('band-straight-arm-pulldown', 'Band Straight Arm Pulldown', 'upper-body-pull', 'pull-vertical', 'band', 'beginner',
   'Lats', '{lats}', '{triceps,rear_delts}', '{abs,forearms,traps}',
   'Strakte arme, træk båndet i en bue ned til lårene med lats, ikke med albuerne.', $ex$["Stå med let fremadlænet overkrop og armene strakte mod ankeret.","Sænk skuldrene væk fra ørerne, før du trækker.","Træk hænderne i en bue ned til lårene med en blød, låst albue.","Klem lats i bunden og hold et sekund.","Før båndet kontrolleret tilbage, til du mærker stræk i lats."]$ex$, $ex$[{"title":"Albuerne bøjer","body":"Bevægelsen bliver til en triceps pushdown. Lås en let bøjning i albuen, og hold den uændret hele vejen."},{"title":"Overkroppen gynger","body":"Du bruger kropsvægten til at flytte båndet. Stå stille med spændt mave, og lad kun skulderleddet bevæge sig."},{"title":"Skuldrene trækkes op","body":"Øvre traps overtager, og lats mister spænding. Hold skuldrene nede og brystet let fremme."}]$ex$,
   'Isolerer lats uden hjælp fra biceps og lærer dig at trække med ryggen. God aktivering før pull-ups og rows.', 'Fastgør båndet højt, over hovedhøjde. Tag fat med overhåndsgreb i skulderbredde, og gå et skridt tilbage, til der er træk i båndet med armene strakte frem og op. Let bøjede knæ og hoften en smule bagud.', 'Brug et tykkere bånd, gå længere væk fra ankeret, eller sænk over tre sekunder. Skift til cable straight arm pulldown for jævn modstand.', 'Brug et lettere bånd og stå tættere på ankeret, eller lav øvelsen knælende for mere stabilitet.',
   1145, false),
  ('band-tricep-kickbacks', 'Band Tricep Kickbacks', 'arms', 'isolation', 'band', 'beginner',
   'Triceps', '{triceps}', '{rear_delts,lats}', '{lower_back,abs,forearms}',
   'Overarmen låst langs kroppen, stræk albuen helt ud bagud, og klem triceps.', $ex$["Bøj frem i hoften med neutral ryg og spændt mave.","Løft overarmene op langs kroppen og hold dem der.","Stræk albuerne helt ud bagud, til armene er lige.","Klem triceps et sekund i toppen.","Bøj langsomt tilbage til 90 grader uden at slippe overarmen."]$ex$, $ex$[{"title":"Overarmen svinger","body":"Skulderen laver arbejdet, og triceps slipper. Hold albuen højt og stille, så kun underarmen bevæger sig."},{"title":"Ufuldstændig strækning","body":"Du stopper, før albuen er strakt, netop hvor båndet er strammest. Vælg et lettere bånd, og lås helt ud."},{"title":"Rund ryg","body":"Overkroppen falder sammen, når du bliver træt. Hold brystet fremme og ryggen neutral, eller støt den frie hånd på en bænk."}]$ex$,
   'Rammer triceps hårdest i den strakte topposition, hvor båndet giver mest modstand. Skånsom mod albuerne og nem at lave hjemme.', 'Stå på midten af båndet med fødderne i hoftebredde, eller fastgør det lavt foran dig. Tag en ende i hver hånd, bøj frem i hoften, til overkroppen er næsten vandret, og træk overarmene op langs siden med albuerne bøjet 90 grader.', 'Brug et tykkere bånd, hold to sekunders pause i toppen, eller sænk over tre sekunder.', 'Brug et lettere bånd, eller lav én arm ad gangen med den frie hånd støttet på en bænk.',
   1145, false),
  ('banded-ankle-dorsiflexion-mobilization', 'Banded Ankle Dorsiflexion Mobilization', 'mobility', 'mobility', 'band', 'beginner',
   'Ankles', '{calves_back,calves_front}', '{quads}', '{glutes,abs}',
   'Hælen i gulvet, kør knæet roligt frem over tæerne, mens båndet trækker anklen bagud.', $ex$["Placér båndet lavt foran på anklen, lige under ankelknoerne.","Hold hælen plantet i gulvet hele tiden.","Kør knæet frem over anden og tredje tå, så langt du kan.","Hold yderpositionen to sekunder, og gå roligt tilbage.","Træk vejret roligt, og gå lidt længere for hver gentagelse."]$ex$, $ex$[{"title":"Hælen løfter","body":"Så snart hælen slipper gulvet, forsvinder strækket i anklen. Gå kun så langt frem, som hælen kan blive nede."},{"title":"Båndet sidder for højt","body":"Sidder det på skinnebenet, trækker det ikke i leddet. Det skal ligge helt nede i folden mellem fod og skinneben."},{"title":"Knæet falder ind","body":"Svangen kollapser, og du snyder dig til bevægelse i foden. Hold svangen løftet og knæet over tæerne."}]$ex$,
   'Bedre dorsalfleksion i anklen giver dybere squat med hælene i gulvet og mere oprejst overkrop. Båndet hjælper leddet med at glide, så du mærker mindre klem foran i anklen.', 'Fastgør et kraftigt bånd lavt bag dig. Sæt løkken om anklen på forreste ben, helt nede i folden mellem fod og skinneben. Gå frem, til båndet er stramt, og stil dig halvt knælende med den forreste fod fladt i gulvet.', 'Sæt forfoden op på en lav forhøjning for større udslag, eller hold yderpositionen i fem sekunder pr. gentagelse.', 'Lav øvelsen uden bånd med tæerne nogle centimeter fra en væg, og før knæet mod væggen med mindre udslag.',
   1155, false),
  ('banded-clamshell', 'Banded Clamshell', 'lower-body', 'isolation', 'band', 'beginner',
   'Glutes', '{glutes}', '{}', '{obliques,abs}',
   'Hælene samlet, hofterne stablet, løft øverste knæ mod båndet uden at rulle bagover.', $ex$["Lig på siden med hofter og knæ bøjet og hælene samlet.","Stabl hofterne lodret over hinanden og spænd maven let.","Løft øverste knæ mod båndet, mens fødderne bliver sammen.","Stop, lige før bækkenet begynder at rulle bagover.","Hold et sekund i toppen og sænk langsomt."]$ex$, $ex$[{"title":"Bækkenet ruller bagover","body":"Du får et større udslag, men arbejdet flytter væk fra gluteus medius. Tip den øverste hofte en smule frem, og hold den der."},{"title":"For hurtige gentagelser","body":"Båndet smækker knæet ned igen, og spændingen forsvinder. Brug to sekunder op og to sekunder ned."},{"title":"Fødderne skilles","body":"Hælene slipper hinanden, og bevægelsen bliver til et benløft. Pres hælene let sammen hele vejen."}]$ex$,
   'Aktiverer gluteus medius og hoftens udadrotatorer, som styrer knæet i squat, udfald og løb. God opvarmning, hvis knæene falder ind.', 'Sæt et minibånd lige over knæene. Lig på siden med hovedet hvilende på underste arm, hofterne bøjet cirka 45 grader og knæene 90 grader. Hælene samlet og hofterne stablet over hinanden.', 'Brug et strammere bånd, hold tre sekunder i toppen, eller lav øvelsen i sideplanke på knæ.', 'Lav øvelsen uden bånd, eller læg ryggen mod en væg, så bækkenet ikke kan rulle.',
   1155, false),
  ('banded-eccentric-tibialis-raise', 'Banded Eccentric Tibialis Raise', 'lower-body', 'isolation', 'band', 'beginner',
   'Tibialis', '{calves_front}', '{}', '{quads}',
   'Træk tæerne hårdt op mod skinnebenet, og sænk foden langsomt over fire sekunder.', $ex$["Sid med strakt ben og båndet om forfoden.","Træk tæerne op mod skinnebenet, så langt du kan.","Hold et sekund i toppen med spændt skinneben.","Sænk foden langsomt over fire til fem sekunder mod båndets træk.","Hold knæ og hofte stille. Kun anklen bevæger sig."]$ex$, $ex$[{"title":"Den langsomme fase springes over","body":"Foden smækker tilbage, og den excentriske træning forsvinder. Tæl til fire på vej ned i hver gentagelse."},{"title":"Kort bevægebane","body":"Du arbejder kun i midten af bevægelsen. Start med strakt vrist, og slut med tæerne helt oppe mod skinnebenet."},{"title":"Båndet glider","body":"Sidder båndet for langt ude på tæerne, glider det af eller trækker i tæerne. Læg det hen over fodryggen ved tåballerne."}]$ex$,
   'Styrker tibialis anterior, som bremser foden ved hver landing i løb og hop. Bruges forebyggende mod skinnebensbetændelse og som modvægt til meget lægtræning.', 'Fastgør båndet lavt foran dig. Sid på gulvet eller en bænk med benet strakt og hælen i underlaget eller lige ud over kanten. Læg løkken om forfoden, og ryk tilbage, til båndet er stramt med strakt vrist.', 'Brug et tykkere bånd, forlæng sænkningen til seks sekunder, eller gå videre til stående tibialis raise med ryggen mod en væg.', 'Brug et lettere bånd og forkort sænkningen til tre sekunder, eller lav bevægelsen uden modstand.',
   1155, false),
  ('barbell-bent-over-row-overhand', 'Barbell Bent-Over Row (Overhand Grip)', 'upper-body-pull', 'pull-horizontal', 'barbell', 'intermediate',
   'Back', '{lats,traps,rear_delts}', '{biceps,forearms,lower_back}', '{hamstrings,glutes,abs}',
   'Bøj frem i hoften, lås ryggen, og træk stangen til nederste ribben med albuerne.', $ex$["Bøj frem i hoften, til overkroppen er lige over vandret, med let bøjede knæ.","Spænd maven og lås ryggen neutral, før du trækker.","Træk stangen mod navlen eller nederste ribben, og før albuerne bagud.","Klem skulderbladene sammen i toppen.","Sænk kontrolleret til strakte arme uden at ændre overkroppens vinkel."]$ex$, $ex$[{"title":"Overkroppen rejser sig","body":"Vægten er for tung, og rækken bliver til et halvt dødløft. Hold vinklen fast, og tag vægt af, hvis hoften skal hjælpe."},{"title":"Rund lænd","body":"Ryggen mister spændingen under belastning. Skub hoften bagud, løft brystet, og hold maven spændt hele sættet."},{"title":"Træk med hænderne","body":"Du krummer håndleddene og trækker med biceps og underarme. Tænk på hænderne som kroge, og træk albuerne bagud."}]$ex$,
   'Bygger tykkelse i hele ryggen og træner evnen til at holde en stærk foroverbøjet position under belastning. Overhåndsgrebet flytter mere arbejde til øvre ryg og bageste skulder.', 'Stå med fødderne i hoftebredde og stangen over midtfoden. Tag overhåndsgreb lidt bredere end skulderbredde. Løft stangen op, og bøj frem i hoften, til overkroppen er lige over vandret, med stangen hængende under skuldrene.', 'Skift til Pendlay row fra gulvet med strikt overkrop, eller tilføj et sekunds pause i toppen.', 'Chest-supported row på skråbænk eller one-arm dumbbell row med støtte, så lænden aflastes.',
   1175, false),
  ('barbell-clean-and-jerk', 'Barbell Clean and Jerk', 'power', 'olympic', 'barbell', 'advanced',
   'Full Body', '{quads,glutes,traps}', '{hamstrings,lower_back,front_delts,triceps}', '{abs,calves_back,forearms,lats}',
   'Træk stangen tæt, eksplodér i hoften, grib den på skuldrene, og stød den op til låste arme.', $ex$["Start med stangen over midtfoden, skuldrene over stangen og flad ryg.","Skub gulvet væk, og hold stangen tæt på kroppen forbi knæene.","Eksplodér i hofte, knæ og ankler, og træk dig hurtigt ned under stangen.","Grib stangen på skuldrene med høje albuer, og rejs dig helt.","Dyp kort og lodret, driv hårdt op, og stød dig ned under stangen til låste arme.","Saml fødderne under dig, og stå stille med stangen over hovedet, før du sænker."]$ex$, $ex$[{"title":"Armene trækker for tidligt","body":"Albuerne bøjer, før hoften er strakt, og kraften fra benene går tabt. Hold armene lange som reb, til hoften er helt strakt."},{"title":"Stangen svinger væk fra kroppen","body":"Hoften slår stangen frem, så du må hoppe efter den. Hold stangen tæt på lår og mave, og træk albuerne op og bagud."},{"title":"Dyppet tipper frem","body":"Brystet falder, og vægten ryger frem på tæerne, så stangen stødes fremad. Dyp kort og lodret med vægten på hele foden og albuerne oppe."}]$ex$,
   'Træner eksplosiv kraft fra gulv til strakte arme og kræver timing, mobilitet og styrke i hele kroppen. Det ene af de to konkurrenceløft i olympisk vægtløftning.', 'Stangen over midtfoden, fødderne i hoftebredde. Tag hook grip lidt bredere end skulderbredde. Hoften ned, brystet op, skuldrene lige foran stangen og armene strakte.', 'Øg vægten gradvist med stabil teknik, eller arbejd med pause over knæet i clean og pause i dyppet før jerk.', 'Del løftet op i hang power clean og push press hver for sig, eller øv hele bevægelsen med kosteskaft eller tom stang.',
   1175, false),
  ('barbell-floor-press', 'Barbell Floor Press', 'upper-body-push', 'push-horizontal', 'barbell', 'intermediate',
   'Chest/Triceps', '{chest,triceps}', '{front_delts}', '{lats,forearms}',
   'Sænk kontrolleret til overarmene rører gulvet, hold et kort stop og pres baren lige op.', $ex$["Træk skulderbladene sammen og ned, før du løfter baren ud.","Sænk baren kontrolleret, til overarmene hviler let på gulvet.","Hold albuerne cirka 45 grader fra kroppen.","Hold et kort stop i bunden uden at slippe spændingen.","Pres baren lige op og lås albuerne ud over skuldrene."]$ex$, $ex$[{"title":"Albuerne hamrer i gulvet","body":"Du taber spændingen og sender stødet op i albuer og håndled. Sænk de sidste centimeter langsomt og land blødt på overarmene."},{"title":"Albuerne stritter helt ud","body":"Lægger pres på skulderleddet og svækker presset. Hold overarmene cirka 45 grader fra kroppen."},{"title":"Håndleddene knækker bagover","body":"Baren ligger for højt i hånden. Hold knoerne mod loftet, så baren står lige over underarmen."}]$ex$,
   'Bygger lockout-styrke i triceps og bryst med en kort bevægebane, der skåner skuldrene. Et godt valg, når almindelig bænkpres driller skulderen.', 'Lig på ryggen i et rack med J-hooks sat lavt, så du kan nå baren med næsten strakte arme. Øjnene under baren, greb lidt bredere end skulderbredde. Bøj knæene med fødderne i gulvet, eller stræk benene helt ud.', 'Hold to sekunders død pause på gulvet, eller pres med strakte ben, så benene ikke kan hjælpe.', 'Dumbbell floor press med lettere vægt, eller push-ups.',
   1205, false),
