   'Forearms', '{forearms}', '{}', '{biceps}',
   'Underarmene i ro, krøl kun håndleddet.', $ex$["Hvil underarmene på lårene med håndfladerne opad.","Lad håndleddene bøje helt bagover i bunden.","Krøl stangen op, så højt håndleddet kan.","Klem i toppen i et sekund.","Sænk langsomt og hold underarmene i kontakt med lårene."]$ex$, $ex$[{"title":"Underarmene løfter sig","body":"Så hjælper biceps med, og underarmen slipper for arbejdet. Hold underarmene presset mod lårene."},{"title":"For tung vægt","body":"Udslaget bliver kort og rykket. Vælg en vægt, du kan styre i 12 til 20 rene gentagelser."},{"title":"Sænkningen springes over","body":"Underarmen reagerer godt på en langsom sænkning. Brug to til tre sekunder på vej ned."}]$ex$,
   'Styrker underarmens bøjere og dermed grebet. Kablet giver jævn modstand i hele udslaget, også i bunden.', 'Sæt en lige stang på den laveste trisse. Sid på en bænk foran maskinen med underhåndsgreb i skulderbredde, underarmene på lårene og håndleddene ud over knæene.', 'Lad stangen rulle ud i fingrene i bunden for længere udslag, eller lav øvelsen med én hånd ad gangen.', 'Dumbbell wrist curl med let vægt og underarmen støttet på en bænk.',
   1745, false),
  ('captains-chair-knee-raise', 'Captain''s Chair Knee Raise', 'core', 'core', 'machine', 'beginner',
   'Abs', '{abs}', '{obliques,quads}', '{lats,traps}',
   'Lænden i puden, knæene op, og rul bækkenet med.', $ex$["Pres underarmene ned i puderne og skuldrene væk fra ørerne.","Hold lænden mod rygpuden.","Pust ud og træk knæene op mod brystet.","Rul bækkenet op og frem i toppen.","Sænk benene langsomt uden at svinge."]$ex$, $ex$[{"title":"Benene svinger","body":"Momentum løfter knæene i stedet for maven. Stop helt i bunden før næste gentagelse."},{"title":"Bækkenet ruller ikke med","body":"Løfter du kun knæene til hoftehøjde, laver hoftebøjerne det meste. Tip bækkenet bagover, så lænden runder let i toppen."},{"title":"Skuldrene synker sammen","body":"Du hænger i leddene. Pres dig aktivt op fra armpuderne og hold brystet åbent."}]$ex$,
   'Træner mavens evne til at tippe bækkenet under belastning, uden at grebet sætter grænsen som i hængende varianter.', 'Træd op i stolen med ryggen mod rygpuden, underarmene på armpuderne og hænderne om håndtagene. Pres skuldrene ned og lad benene hænge lige ned.', 'Løft strakte ben (leg raise), eller hold en let håndvægt mellem fødderne.', 'Løft ét knæ ad gangen, eller lav reverse crunch på gulvet.',
   1745, false),
