   'Biceps', '{biceps}', '{forearms}', '{front_delts,abs,lower_back}',
   'Smalt greb, albuerne låst ved siden, krøl uden sving.', $ex$["Stå rank med spændt mave og baller.","Hold albuerne ind til kroppen. De bliver, hvor de er.","Krøl stangen op i en bue mod brystet.","Klem biceps i toppen.","Sænk over to til tre sekunder til strakte arme."]$ex$, $ex$[{"title":"Sving med overkroppen","body":"Du læner dig bagover og kaster stangen op. Tag vægt af, eller stil dig med ryggen mod en væg."},{"title":"Albuerne vandrer frem","body":"Forreste skulder overtager, og biceps får pause i toppen. Hold albuerne ved ribbenene."},{"title":"Håndleddene knækker bagover","body":"Det smalle greb på en lige stang kan stresse håndleddene. Hold dem neutrale, og skift til EZ-bar, hvis det gør ondt."}]$ex$,
   'Det smalle greb flytter mere arbejde over på biceps'' lange hoved, den ydre del af overarmen. En simpel variation af den klassiske curl.', 'Stå med fødderne i hoftebredde. Grib stangen med underhåndsgreb, hænderne smallere end skulderbredde, cirka 15 til 20 cm fra hinanden. Stangen hviler mod lårene, armene strakte, albuerne tæt til kroppen.', 'Sænk over fire sekunder, eller lav øvelsen med ryggen mod en væg, så alt snyd forsvinder.', 'EZ-bar curl med smalt greb skåner håndleddene, eller dumbbell curl med let vægt.',
   1755, false),
  ('close-grip-incline-push-up', 'Close Grip Incline Push-Up', 'upper-body-push', 'push-horizontal', 'bodyweight', 'beginner',
   'Triceps/Chest', '{triceps,chest}', '{front_delts}', '{abs,glutes,quads}',
   'Hænderne smalt, albuerne langs kroppen, kroppen som en planke.', $ex$["Spænd mave og baller, så kroppen er én lige linje.","Hold albuerne tæt langs ribbenene på vej ned.","Sænk brystet helt ned til kanten.","Pres dig op til strakte arme.","Hold nakken lang og blikket lidt foran hænderne."]$ex$, $ex$[{"title":"Hoften hænger","body":"Lænden svajer, og maven er slået fra. Spænd ballerne og træk ribbenene ned mod hoften."},{"title":"Albuerne peger ud til siden","body":"Flytter arbejdet væk fra triceps og stresser skulderen. Hold albuerne ind, så de peger bagud."},{"title":"Halve gentagelser","body":"Brystet skal ned til kanten, og armene skal strækkes helt. Vælg et højere underlag, hvis du ikke kan."}]$ex$,
   'Træner triceps og bryst med en mindre del af kropsvægten end på gulvet. Et solidt trin på vejen mod close grip push-up og dips.', 'Sæt hænderne på en bænk, kasse eller fastlåst stang, lidt smallere end skulderbredde. Gå fødderne bagud, til kroppen er en lige linje fra hoved til hæl. Armene strakte, skuldrene over hænderne.', 'Sænk underlaget trin for trin, til du laver close grip push-up på gulvet.', 'Brug et højere underlag, fx en bordkant, eller lav øvelsen mod en væg.',
   1755, false),
  ('controlled-forearm-pronation-supination', 'Controlled Forearm Pronation/Supination', 'mobility', 'mobility', 'bodyweight', 'beginner',
   'Forearms', '{forearms}', '{biceps}', '{}',
   'Albuen fast ved siden, drej håndfladen langsomt op og ned.', $ex$["Hold albuen bøjet 90 grader og presset ind mod siden.","Drej håndfladen langsomt op mod loftet, så langt du kan.","Drej langsomt tilbage, til håndfladen peger mod gulvet.","Brug tre til fire sekunder hver vej og træk vejret roligt.","Hold skulder og håndled i ro. Rotationen kommer fra underarmen."]$ex$, $ex$[{"title":"Skulderen snyder med","body":"Når albuen løfter sig fra siden, kommer rotationen fra skulderen. Klem et sammenrullet håndklæde mellem albue og ribben."},{"title":"For hurtigt tempo","body":"Sving giver hverken kontrol eller bevægelighed. Bevæg dig langsomt og stop et sekund i hver yderposition."},{"title":"Håndleddet bøjer","body":"Håndleddet vipper, i stedet for at underarmen drejer. Hold hånden i forlængelse af underarmen."}]$ex$,
   'Vedligeholder underarmens rotation og styrker de små muskler omkring albuen. Nyttig som opvarmning før greb- og trækarbejde og efter mange timer ved tastaturet.', 'Stå eller sid rank. Bøj albuen 90 grader, hold den ind mod siden, og start med tommelfingeren pegende op. Hånden er åben eller let knyttet.', 'Hold en let håndvægt eller en hammer i den ene ende, så vægtarmen gør rotationen tungere.', 'Støt underarmen på et bord eller på låret, og gør udslaget mindre.',
   1755, false),
  ('copenhagen-plank', 'Copenhagen Plank', 'core', 'core', 'bodyweight', 'intermediate',
   'Adductors/Obliques', '{adductors,obliques}', '{abs,glutes}', '{front_delts,lower_back}',
   'Pres øverste ben ned i bænken og hold kroppen som en lige planke.', $ex$["Placér albuen lige under skulderen og pres underarmen i gulvet.","Pres øverste ben ned i bænken og løft hoften, til kroppen er en lige linje.","Løft nederste ben op under bænken og hold det der.","Spænd mave og baller, så hoften hverken synker eller roterer.","Træk vejret roligt gennem hele holdet."]$ex$, $ex$[{"title":"Hoften synker","body":"Belastningen flytter fra inderlår og sidemave over i skulder og lænd. Stop sættet, når du ikke længere kan holde en lige linje fra skulder til ankel."},{"title":"Kroppen roterer","body":"Hoften drejer frem eller tilbage, og adduktorerne slipper. Hold hofter og skuldre stablet lodret over hinanden."},{"title":"For lang vægtstang for tidligt","body":"Støtte ved anklen giver stort træk i lysken og på indersiden af knæet. Start med knæet på bænken og arbejd dig gradvist ud."}]$ex$,
   'Styrker adduktorerne under høj belastning og er en af de bedst dokumenterede øvelser til at forebygge lyskeskader. Bygger samtidig stabilitet i siden af kroppen.', 'Lig på siden ved en bænk med underarmen i gulvet og albuen under skulderen. Læg indersiden af øverste fod eller ankel på bænken, og lad nederste ben hænge frit under den.', 'Lav dynamiske gentagelser, hvor hoften sænkes og løftes, eller forlæng holdet til 30 sekunder pr. side med støtte ved anklen.', 'Kort vægtstang: læg knæet på bænken i stedet for anklen, eller lad nederste fod blive i gulvet som støtte.',
   1755, false),
  ('cossack-squat', 'Cossack Squat', 'lower-body', 'squat', 'bodyweight', 'intermediate',
   'Quads/Glutes', '{quads,glutes,adductors}', '{hamstrings}', '{abs,lower_back,calves_back}',
   'Sæt dig dybt over det ene ben, hælen i gulvet, det andet ben strakt.', $ex$["Flyt vægten over på det ene ben og sæt dig ned over hælen.","Hold hælen på det bøjede ben i gulvet og knæet i retning af tæerne.","Stræk det andet ben helt og lad tæerne pege mod loftet.","Hold brystet oppe og ryggen lang.","Pres gennem hele foden og skift side gennem midten."]$ex$, $ex$[{"title":"Hælen løfter sig","body":"Vægten ryger frem på forfoden, og knæet tager belastningen. Gå kun så dybt, som du kan med hele foden i gulvet, eller hold fast i en støtte."},{"title":"Knæet falder ind","body":"Det bøjede knæ kollapser indad i bunden. Pres knæet ud over lilletåen hele vejen ned og op."},{"title":"Ryggen runder","body":"Overkroppen falder frem for at kompensere for stive hofter. Hold en let vægt foran brystet som modvægt og reducér dybden."}]$ex$,
   'Træner styrke i sideværts retning, som almindelige squats og lunges ikke rammer, og giver adduktorerne et belastet stræk. Forbedrer hofte- og ankelmobilitet på samme tid.', 'Stå bredt, cirka dobbelt skulderbredde, med tæerne let udad. Saml hænderne foran brystet som modvægt og spænd maven.', 'Hold en kettlebell i goblet-position, eller tilføj to sekunders pause i bunden.', 'Hold fast i et stativ eller en TRX for balance, eller gå kun til halv dybde.',
   1755, false),
  ('cross-body-cable-tricep-extension', 'Cross Body Cable Tricep Extension', 'arms', 'isolation', 'cable', 'beginner',
   'Triceps', '{triceps}', '{}', '{rear_delts,forearms,abs}',
   'Albuen låst ved siden, stræk armen ned og ud på tværs af kroppen.', $ex$["Lås overarmen ind til siden af kroppen.","Stræk albuen ned og ud væk fra kroppen, til armen er helt strakt.","Klem triceps hårdt i bunden i et sekund.","Lad hånden vende langsomt tilbage mod modsatte skulder.","Hold skulderen nede og overkroppen stille."]$ex$, $ex$[{"title":"Albuen vandrer","body":"Overarmen svinger med, og skulder og lats overtager arbejdet. Hold albuen fast ved siden, så kun underarmen bevæger sig."},{"title":"For tung vægt","body":"Kroppen roterer og læner sig ind i trækket. Vælg en vægt, du kan styre i tre sekunder på vej tilbage."},{"title":"Halv bevægelse","body":"Albuen strækkes ikke helt, eller returen stoppes for tidligt. Arbejd fra dybt bøjet til helt strakt arm i hver gentagelse."}]$ex$,
   'Trækket på tværs af kroppen giver triceps konstant spænding i hele bevægelsen og er skånsomt for albuerne. Én arm ad gangen afslører og udligner forskelle mellem siderne.', 'Sæt trissen i cirka hovedhøjde. Stå med siden til maskinen og grib kablet med den modsatte hånd (uden håndtag eller med D-håndtag), så det krydser foran kroppen. Overarmen ved siden, albuen bøjet.', 'Kør begge arme samtidig med krydsede kabler, eller sænk over tre sekunder på vej tilbage.', 'Almindelig cable pushdown med reb og begge hænder, eller lettere vægt og flere gentagelser.',
   1755, false),
  ('cross-body-hammer-curl', 'Cross Body Hammer Curl', 'arms', 'isolation', 'dumbbell', 'beginner',
   'Biceps/Forearms', '{biceps,forearms}', '{}', '{front_delts,traps,abs}',
   'Tommelfingeren op, curl på tværs mod modsatte skulder, albuen i ro.', $ex$["Hold håndfladen mod kroppen gennem hele bevægelsen.","Curl vægten op på tværs af kroppen mod modsatte skulder.","Hold albuen ved siden af kroppen. Kun underarmen flytter sig.","Klem i toppen og sænk langsomt til helt strakt arm.","Skift arm for hver gentagelse uden at svinge med kroppen."]$ex$, $ex$[{"title":"Sving med overkroppen","body":"Hofte og ryg kaster vægten op, og armbøjerne slipper for arbejdet. Stå stille, spænd maven og gå ned i vægt."},{"title":"Albuen flytter frem","body":"Skulderen overtager, og spændingen i toppen forsvinder. Hold albuen låst ved siden af kroppen."},{"title":"Hånden roterer","body":"Drejer du håndfladen op undervejs, bliver det en almindelig curl. Hold tommelfingeren opad hele vejen."}]$ex$,
   'Det neutrale greb flytter belastningen til brachialis og brachioradialis, som giver tykkelse i overarmen og styrke i underarmen. Stærkere albuebøjere løfter alle trækøvelser.', 'Stå oprejst med en håndvægt i hver hånd og neutralt greb (håndfladerne mod lårene). Skuldrene nede, albuerne tæt ved kroppen, spændt mave.', 'Sænk over tre til fire sekunder, eller udfør øvelsen siddende med ryglæn, så alt sving fjernes.', 'Almindelig hammer curl lige op og ned med lettere vægt, eller træn én arm ad gangen med den frie hånd som støtte.',
   1755, false),
  ('crunches', 'Crunches', 'core', 'core', 'bodyweight', 'beginner',
   'Abs', '{abs}', '{obliques}', '{neck}',
   'Rul skulderbladene fri af gulvet og træk ribbenene mod hoften.', $ex$["Pres lænden let ned i måtten, før du starter.","Pust ud og rul skulderbladene fri af gulvet.","Træk ribbenene ned mod hoften. Tænk kort og rund bevægelse.","Hold afstand mellem hage og bryst og blikket skråt op.","Sænk langsomt uden at slippe spændingen i bunden."]$ex$, $ex$[{"title":"Trækker i nakken","body":"Hænderne hiver hovedet frem, og nakken tager belastningen. Lad fingrene hvile let ved tindingerne og løft med maven."},{"title":"Sætter sig helt op","body":"Går du videre end skulderbladene, overtager hoftebøjerne. Stop, når skulderbladene er fri af gulvet."},{"title":"Fart og sving","body":"Tempo fjerner spændingen fra mavemusklerne. Brug to sekunder op og to sekunder ned."}]$ex$,
   'Træner den lige mavemuskel gennem bøjning af rygsøjlen, som planker ikke dækker. Enkel at lære og nem at belaste progressivt.', 'Lig på ryggen på en måtte med bøjede knæ og fødderne fladt i gulvet. Hænderne let ved tindingerne eller krydset over brystet.', 'Hold en vægtskive på brystet, eller skift til cable crunch for tungere belastning.', 'Gør udslaget mindre og ræk armene frem langs lårene, eller lav dead bug for at lære mavespændingen.',
   1755, false),
  ('cuban-press', 'Cuban Press', 'shoulders', 'push-vertical', 'dumbbell', 'intermediate',
   'Shoulders/Rotator Cuff', '{rear_delts,front_delts}', '{traps,triceps}', '{abs,forearms}',
   'Albuer op, rotér, pres, og samme vej kontrolleret ned.', $ex$["Træk albuerne op og ud til skulderhøjde, så underarmene hænger lodret.","Hold albuerne stille og rotér underarmene op, til knoerne peger mod loftet.","Pres vægtene lige op over hovedet til strakte arme.","Gå samme vej tilbage: sænk, rotér ned, sænk albuerne.","Hold ribbenene nede og undgå at svaje i lænden.","Brug let vægt og roligt tempo i hver fase."]$ex$, $ex$[{"title":"For tung vægt","body":"Rotatorcuffen er en lille muskelgruppe, og tung vægt gør rotationen til et kast. Start med 2 til 5 kg og kontrollér hver fase."},{"title":"Albuerne falder under rotationen","body":"Når albuerne synker, forsvinder udadrotationen, og øvelsen bliver et almindeligt pres. Hold overarmene vandret, mens underarmene drejer."},{"title":"Svaj i lænden","body":"Ribbenene løfter sig for at kompensere for manglende skuldermobilitet. Spænd mave og baller, og pres kun så højt, du kan med neutral ryg."}]$ex$,
   'Styrker skulderens udadrotatorer sammen med deltamusklerne og giver mere stabile skuldre til tunge pres. Fungerer godt som opvarmning eller forebyggende træning med let vægt.', 'Stå oprejst med en let håndvægt i hver hånd foran lårene, overhåndsgreb. Fødderne i hoftebredde, spændt mave og skuldrene nede.', 'Brug tre sekunder på rotationen ned, eller skift til en let vægtstang, så begge sider skal arbejde synkront.', 'Lav kun rotationsdelen med albuerne i skulderhøjde og uden pres, eller brug et let elastikbånd.',
   1755, false),
  ('cycling-cooldown', 'Cycling Cooldown', 'cardio', 'conditioning', 'cardio-machine', 'beginner',
   'Legs', '{quads,glutes}', '{hamstrings,calves_back}', '{abs,lower_back}',
   'Lav modstand, rolige ben, lad pulsen falde gradvist.', $ex$["Skru modstanden ned, så benene kører uden pres.","Hold en rolig kadence omkring 70 til 85 omdrejninger i minuttet.","Træk vejret dybt ned i maven og forlæng udåndingen.","Slip spændingen i skuldre og hænder, og sid afslappet.","Sænk intensiteten trinvist, til du kan tale i hele sætninger."]$ex$, $ex$[{"title":"Stopper brat","body":"Stiger du direkte af efter hårdt arbejde, kan du blive svimmel, fordi blodet samler sig i benene. Kør mindst tre til fem minutter let, før du står af."},{"title":"For høj intensitet","body":"Nedkøling er ikke ekstra træning. Pulsen skal falde, så hold dig på et niveau, hvor du kan føre en samtale."},{"title":"Sammensunket holdning","body":"Rund ryg og låste skuldre holder spændingen i kroppen. Ret dig op, løsn grebet og lad skuldrene falde."}]$ex$,
   'Bringer puls og vejrtrækning roligt ned efter hårdt arbejde og holder blodet i gang i benene. Giver en kontrolleret overgang fra træning til hvile.', 'Sid på cyklen med sadlen i en højde, hvor knæet er let bøjet i bunden af trådet. Lav modstand og et afslappet greb om styret.', 'Forlæng nedkølingen til 10 minutter efter særligt hårde pas, og afslut med let udstrækning af hofter og lår.', 'Kør tre minutter med næsten ingen modstand, eller gå roligt rundt, hvis du ikke kan sidde på cyklen.',
   1755, false),
  ('cycling-intervals', 'Cycling Intervals', 'cardio', 'conditioning', 'cardio-machine', 'intermediate',
   'Legs', '{quads,glutes}', '{hamstrings,calves_back}', '{abs,lower_back}',
   'Hårdt i arbejdsperioden, helt let i pausen, samme kvalitet i hvert interval.', $ex$["Varm op i fem til ti minutter før første interval.","Kør arbejdsperioden så hårdt, at du kun kan sige enkelte ord.","Hold kadencen på 85 til 100 omdrejninger og styr belastningen med modstanden.","Kør pausen helt let og få vejret ned før næste interval.","Hold overkroppen stille og tråd rundt hele vejen.","Sigt efter samme watt i sidste interval som i første."]$ex$, $ex$[{"title":"Åbner for hårdt","body":"Første interval køres som en sprint, og resten falder fra hinanden. Fordel kræfterne, så sidste interval matcher det første."},{"title":"For hårde pauser","body":"Uden reel restitution kan du ikke ramme intensiteten i næste arbejdsperiode. Skru modstanden helt ned og lad pulsen falde."},{"title":"Lav kadence med tung modstand","body":"Tunge gear ved få omdrejninger belaster knæene og dræner benene for tidligt. Hold omdrejningerne oppe og justér modstanden derefter."}]$ex$,
   'Intervaller hæver kondition og iltoptagelse hurtigere end jævnt tempo på samme tid. Cyklen giver høj puls uden stødbelastning på leddene.', 'Indstil sadlen, så knæet er let bøjet i bunden af trådet, og styret, så ryggen er lang. Vælg struktur på forhånd, fx 4 x 4 minutter hårdt med 3 minutters let pause.', 'Tilføj et ekstra interval, forlæng arbejdsperioden, eller forkort pausen.', 'Kør kortere arbejdsperioder (fx 1 minut hårdt, 2 minutter let) og færre gentagelser.',
   1755, false),
  ('cycling-sprint', 'Cycling Sprint', 'cardio', 'conditioning', 'cardio-machine', 'intermediate',
   'Legs', '{quads,glutes,hamstrings}', '{calves_back}', '{abs,lower_back,forearms}',
   'Alt hvad du har i få sekunder, og fuld pause før næste.', $ex$["Varm grundigt op og kør et par korte accelerationer først.","Spark fra første pedaltråd og giv maksimal indsats i hele sprinten.","Hold fast om styret og overkroppen stabil.","Hold hoften i ro over sadlen, så kraften går i pedalerne.","Rul helt let i pausen, til du kan levere samme kvalitet igen."]$ex$, $ex$[{"title":"Sparer på kræfterne","body":"En sprint på 80 procent er et interval, ikke en sprint. Hold varigheden kort (10 til 30 sekunder) og giv alt."},{"title":"For kort pause","body":"Uden fuld restitution falder effekten, og du træner udholdenhed i stedet for topfart. Hold to til fire minutters let tråd mellem sprinterne."},{"title":"For let modstand","body":"Benene spinner ud uden at møde modstand, og effekten bliver lav. Skru op, så du kan presse hårdt gennem hele sprinten."}]$ex$,
   'Maksimale sprinter træner topeffekt og anaerob kapacitet på meget kort tid. På cyklen kan du give alt med lavere skadesrisiko for baglårene end ved løbesprint.', 'Indstil sadlen, så knæet er let bøjet i bunden af trådet, og spænd fødderne fast i pedalerne. Vælg en modstand, der er tung nok til, at benene ikke spinner ud.', 'Tilføj flere sprinter, øg modstanden, eller forlæng sprinten fra 10 til 30 sekunder.', 'Kør kortere sprinter på 6 til 8 sekunder ved cirka 90 procent indsats med lang pause imellem.',
   1755, false),
  ('cycling-warmup', 'Cycling Warmup', 'cardio', 'conditioning', 'cardio-machine', 'beginner',
   'Legs', '{quads,glutes}', '{hamstrings,calves_back}', '{abs}',
   'Start let, byg gradvist op, slut varm og let forpustet.', $ex$["Start med lav modstand og rolig kadence de første par minutter.","Skru gradvist op, til du er let forpustet, men stadig kan tale.","Hold kadencen omkring 80 til 90 omdrejninger i minuttet.","Træk vejret roligt og dybt, og hold skuldrene afslappede.","Afslut med to til tre korte accelerationer, hvis passet er hårdt."]$ex$, $ex$[{"title":"For hårdt for tidligt","body":"Opvarmningen bliver et træningspas og tager kræfter fra hoveddelen. Hold dig under det niveau, hvor benene begynder at syre til."},{"title":"For kort","body":"To minutter på cyklen hæver hverken puls eller kropstemperatur nok. Brug fem til ti minutter."},{"title":"Forkert sadelhøjde","body":"For lav sadel presser knæene, for høj får hoften til at vugge. Knæet skal være let bøjet i bunden af trådet."}]$ex$,
   'Hæver puls, kropstemperatur og blodgennemstrømning i benene, så led og muskler er klar til belastning. Skånsom for knæ og ankler, fordi der ikke er nogen stød.', 'Indstil sadlen, så knæet er let bøjet i bunden af trådet. Sæt modstanden lavt og tag et afslappet greb om styret.', 'Forlæng til 10 minutter og læg tre korte accelerationer på 10 sekunder ind til sidst.', 'Kør tre til fem minutter med let modstand i et tempo, hvor du kan tale ubesværet.',
   1755, false),
  ('dead-bug', 'Dead Bug', 'core', 'core', 'bodyweight', 'beginner',
   'Abs', '{abs}', '{obliques}', '{quads,front_delts}',
   'Pres lænden i gulvet og stræk modsat arm og ben langsomt ud.', $ex$["Pres lænden ned i gulvet og hold den der hele vejen.","Stræk modsat arm og ben ud, til de svæver lige over gulvet.","Pust ud, mens du strækker, og træk ribbenene ned mod hoften.","Hold det andet knæ over hoften, mens du skifter side.","Bevæg dig langsomt. Kun arme og ben flytter sig, kroppen ligger stille."]$ex$, $ex$[{"title":"Lænden svajer","body":"Lænden slipper gulvet, når benet strækkes, og maven mister spændingen. Stræk kun benet så langt ud, at du kan holde lænden nede."},{"title":"For højt tempo","body":"Fart skjuler manglende kontrol. Brug to til tre sekunder på vej ud og det samme tilbage."},{"title":"Holder vejret","body":"Du spænder op med vejret i stedet for maven. Pust roligt ud på hver udstrækning."}]$ex$,
   'Lærer dig at holde ryggen stabil, mens arme og ben bevæger sig. Det er grundlaget for squat, dødløft og løb.', 'Lig på ryggen med armene strakt mod loftet og hofter og knæ bøjet 90 grader. Pres lænden mod gulvet og spænd maven.', 'Hold en let håndvægt i hver hånd (weighted dead bug), eller hold en pause på tre sekunder i yderpositionen.', 'Bevæg kun benene og lad armene blive oppe, eller sæt hælen let i gulvet på hver gentagelse.',
   1755, false),
  ('dead-bug-weighted', 'Weighted Dead Bug', 'core', 'core', 'dumbbell', 'intermediate',
   'Abs', '{abs}', '{obliques}', '{front_delts,lats,quads}',
   'Lænden i gulvet, og lad ikke vægten trække ribbenene op.', $ex$["Pres lænden i gulvet, før vægten bevæger sig.","Sænk modsat arm og ben langsomt mod gulvet.","Hold ribbenene nede, når håndvægten går bagud over hovedet.","Pust ud på vej ud, træk vejret ind på vej tilbage.","Stop udslaget, lige før lænden vil slippe gulvet."]$ex$, $ex$[{"title":"Ribbenene flyver op","body":"Vægten over hovedet trækker brystkassen med, og lænden svajer. Gå ned i vægt og forkort udslaget, til du kan holde ribbenene nede."},{"title":"For tung vægt","body":"Skuldrene overtager, og maven taber spændingen. Øvelsen handler om kontrol af kroppen, ikke om at flytte mange kilo."},{"title":"Bøjet arm","body":"Albuen bøjer for at gøre vægtarmen kortere. Hold armen strakt og vælg en lettere håndvægt."}]$ex$,
   'Den ekstra vægt øger kravet til at modstå svaj i lænden. Det overfører direkte til overhead pres og tunge løft, hvor ribben og bækken skal blive stående over hinanden.', 'Lig på ryggen med en let håndvægt i hver hånd og armene strakt over skuldrene. Hofter og knæ i 90 grader, lænden presset mod gulvet.', 'Øg vægten gradvist, tilføj ankelvægte, eller hold tre sekunders pause i yderpositionen.', 'Almindelig dead bug uden vægt, eller hold én vægt stille over brystet og bevæg kun benene.',
   1755, false),
  ('dead-hang', 'Dead Hang', 'upper-body-pull', 'pull-vertical', 'bodyweight', 'beginner',
   'Forearms', '{forearms}', '{lats,traps}', '{biceps,abs,rear_delts}',
   'Grib fast om stangen, stræk armene helt, og hæng stille med rolig vejrtrækning.', $ex$["Grib stangen i skulderbredde med tommelfingeren rundt om.","Stræk armene helt og lad kroppen hænge lang.","Hold ribbenene nede og benene samlet, så du ikke svajer.","Træk vejret roligt gennem næsen, mens du hænger.","Træd kontrolleret ned, før grebet glider."]$ex$, $ex$[{"title":"Kroppen svinger","body":"Sving gør grebet sværere at holde og belaster skuldrene ujævnt. Spænd let i maven, saml benene og find ro, før tiden starter."},{"title":"Kun fingerspidserne bærer","body":"Stangen ligger yderst i fingrene, og grebet åbner sig hurtigt. Læg stangen dybt i hånden og luk tommelfingeren rundt om."},{"title":"Holder vejret","body":"Spændingen stiger, og du slipper for tidligt. Træk vejret roligt og jævnt hele vejen."}]$ex$,
   'Bygger grebsstyrke og udholdenhed i underarmene og giver skuldre og rygsøjle et langt træk. Et stærkt hæng er fundamentet for pull-ups og tunge træk.', 'Stil dig under en pull-up stang, eventuelt på en kasse. Grib i skulderbredde med overhåndsgreb og løft fødderne fra underlaget.', 'Forlæng tiden, hæng i én arm, eller tilføj vægt i et bælte. Aktivt hæng med skulderbladene trukket ned er næste skridt mod pull-ups.', 'Lad tæerne hvile på en kasse eller i en elastik, så benene bærer en del af vægten. Start med 10 til 15 sekunder ad gangen.',
   1755, false),
  ('decline-barbell-bench-press', 'Decline Barbell Bench Press', 'upper-body-push', 'push-horizontal', 'barbell', 'intermediate',
   'Chest', '{chest,triceps}', '{front_delts}', '{lats,traps,forearms}',
   'Skulderblade sammen, sænk stangen til nederste del af brystet, og pres lige op.', $ex$["Lås benene fast under puderne, før du løfter stangen af.","Træk skulderbladene sammen og ned i bænken.","Sænk stangen kontrolleret til nederste del af brystet.","Hold albuerne cirka 45 grader fra kroppen.","Hold håndleddene lige over albuerne.","Pres stangen op til strakte arme over skuldrene."]$ex$, $ex$[{"title":"Stangen lander for højt","body":"På en decline bænk driver stangen mod halsen, hvis du sænker for højt. Sigt efter nederste del af brystbenet og hold underarmene lodrette."},{"title":"Stangen hopper på brystet","body":"Du mister spændingen i brystet og kontrollen over stangen. Sænk på to sekunder og rør brystet let."},{"title":"Løfter af uden spotter","body":"Vinklen gør det svært at få stangen ud og tilbage i holderne alene. Brug en spotter, når vægten bliver tung."}]$ex$,
   'Lægger belastningen på den nederste del af brystet og aflaster skuldrene i forhold til flad og incline bænkpres. Bevægebanen er kort, så mange kan løfte lidt tungere end på flad bænk.', 'Indstil bænken til 15 til 30 graders decline og lås benene under puderne. Lig med øjnene under stangen, grib lidt bredere end skulderbredde, og træk skulderbladene sammen.', 'Tilføj en pause på brystet, eller sænk på tre til fire sekunder.', 'Decline machine chest press, eller decline pres med håndvægte og lettere belastning.',
   1755, false),
  ('decline-crunch', 'Decline Crunch', 'core', 'core', 'bodyweight', 'intermediate',
   'Abs', '{abs}', '{obliques}', '{quads}',
   'Rul ryggen op fra bænken ét led ad gangen, og træk ribbenene mod hoften.', $ex$["Lås fødderne under puderne og læg fingrene ved tindingerne.","Pust ud og rul overkroppen op, til skulderbladene er fri af bænken.","Træk ribbenene mod hoften. Lænden bliver i bænken.","Hold en knytnæves afstand mellem hage og bryst.","Sænk langsomt tilbage uden at slappe af i bunden."]$ex$, $ex$[{"title":"Hiver i nakken","body":"Hænderne trækker hovedet frem, og nakken tager belastningen. Læg fingrene let ved tindingerne og lad maven løfte."},{"title":"Bliver til en sit up","body":"Hele ryggen løfter fra bænken, og hoftebøjerne overtager. Stop, når skulderbladene er fri, og hold lænden i bænken."},{"title":"Falder ned i bunden","body":"Du taber spændingen og den sænkende fase, som er halvdelen af arbejdet. Sænk på to til tre sekunder."}]$ex$,
   'Hældningen giver maven modstand gennem et længere stræk end en crunch på gulvet. Effektiv til at bygge de lige mavemuskler med meget lidt udstyr.', 'Indstil en decline bænk til 15 til 30 grader og lås fødderne under puderne. Lig med ryggen i bænken, knæene bøjet og fingrene ved tindingerne eller armene krydset over brystet.', 'Hold en vægtskive mod brystet, eller gør bænken stejlere.', 'Crunch på gulvet, eller sænk bænkens hældning.',
   1755, false),
  ('decline-machine-chest-press', 'Decline Machine Chest Press', 'upper-body-push', 'push-horizontal', 'machine', 'beginner',
   'Chest', '{chest}', '{triceps,front_delts}', '{traps}',
   'Skulderblade tilbage i ryglænet, pres håndtagene frem og ned, og sænk kontrolleret.', $ex$["Indstil sædet, så håndtagene sidder ud for nederste del af brystet.","Træk skulderbladene sammen og hold dem mod ryglænet.","Pres håndtagene frem, til armene er næsten strakte.","Hold albuerne lidt under skulderhøjde.","Sænk langsomt, til du mærker stræk i brystet.","Hold fødderne i gulvet og ryggen mod puden."]$ex$, $ex$[{"title":"Skuldrene ruller frem","body":"Skulderbladene slipper ryglænet i toppen, og skuldrene tager over fra brystet. Hold brystet højt og stop presset, lige før skuldrene følger med."},{"title":"Forkert sædehøjde","body":"Sidder håndtagene for højt, rammer du skulderen i stedet for nederste bryst. Juster sædet, så håndtagene flugter med nederste del af brystet."},{"title":"Halve gentagelser","body":"For tung vægt forkorter bevægelsen, og brystet får aldrig stræk. Tag vægt af og brug hele banen."}]$ex$,
   'Rammer nederste del af brystet i en fast bane, så du kan presse tæt på udmattelse uden spotter. God til begyndere og som volumenarbejde efter tunge pres.', 'Indstil sædet, så håndtagene er ud for nederste del af brystet. Sæt dig med ryg og hoved mod puden, fødderne i gulvet og skulderbladene trukket sammen.', 'Sænk på tre til fire sekunder, tilføj en pause i strækket, eller pres med én arm ad gangen.', 'Sænk vægten og arbejd i det udslag, du kan styre, eller brug en almindelig chest press maskine.',
   1755, false),
  ('decline-sit-up', 'Decline Sit-Up', 'core', 'core', 'bodyweight', 'intermediate',
   'Abs', '{abs}', '{quads,obliques}', '{calves_front}',
   'Rul hele overkroppen op mod knæene, og sænk dig langsomt tilbage under kontrol.', $ex$["Lås fødderne under puderne og kryds armene over brystet.","Pust ud og rul op, først skuldre, så ryg.","Kom helt op, til brystet nærmer sig lårene.","Sænk dig langsomt, ét led ad gangen.","Vend, lige før skuldrene hviler på bænken."]$ex$, $ex$[{"title":"Kaster overkroppen op","body":"Sving med arme og hoved flytter arbejdet væk fra maven. Kryds armene over brystet og start hver gentagelse uden tilløb."},{"title":"Svajer i lænden","body":"Lænden hænger i bunden, og hoftebøjerne trækker i lænderyggen. Rund ryggen let og hold ribbenene nede hele vejen."},{"title":"Falder tilbage","body":"Den sænkende fase er halvdelen af øvelsen. Brug to til tre sekunder på vej ned."}]$ex$,
   'Træner mave og hoftebøjere gennem fuld bevægelse mod tyngdekraften. Bygger den styrke i kropsbøjning, som crunches alene ikke giver.', 'Indstil en decline bænk til 20 til 30 grader og lås fødder og underben under puderne. Lig tilbage med knæene bøjet og armene krydset over brystet.', 'Hold en vægtskive mod brystet eller i strakte arme over hovedet, eller gør bænken stejlere.', 'Decline crunch, sit up på gulvet, eller lavere hældning på bænken.',
   1765, false),
  ('deficit-barbell-romanian-deadlift', 'Deficit Barbell Romanian Deadlift', 'lower-body', 'hinge', 'barbell', 'advanced',
   'Hamstrings', '{hamstrings,glutes}', '{lower_back,adductors}', '{forearms,traps,lats,abs}',
   'Hoften langt tilbage, stangen tæt på benene, og sænk til baglårene siger stop.', $ex$["Stå på en vægtskive eller lav kasse med stangen i strakte arme.","Træk skuldrene ned og hold lats spændte.","Skub hoften bagud og lad knæene være let bøjede.","Hold stangen tæt mod lår og skinneben hele vejen.","Sænk, så længe ryggen er neutral. Stop, når hoften ikke kan komme længere tilbage.","Driv hoften frem og spænd ballerne i toppen."]$ex$, $ex$[{"title":"Ryggen runder i bunden","body":"Du jagter dybden med ryggen, når baglårene ikke kan give mere. Forhøjningen giver plads, ikke pligt: stop, hvor hoften holder op med at bevæge sig bagud."},{"title":"Bliver til en squat","body":"Knæene bøjer mere og mere for at nå længere ned, og baglårene mister strækket. Hold knævinklen fast og lad hoften lave bevægelsen."},{"title":"Stangen driver væk fra kroppen","body":"Vægtarmen på lænden vokser. Spænd lats og lad stangen glide langs benene."}]$ex$,
   'Forhøjningen forlænger bevægelsen, så baglår og baller arbejder i et dybere stræk under belastning. Det bygger styrke og muskelmasse i den lange position.', 'Stå på en vægtskive eller lav kasse (5 til 10 cm) med fødderne i hoftebredde. Løft stangen til stående med greb lige uden for lårene og skuldrene trukket ned.', 'Sænk på fire sekunder, tilføj en pause i bunden, eller øg forhøjningen lidt.', 'Almindelig Romanian deadlift fra gulvniveau, eller Romanian deadlift med håndvægte.',
   1765, false),
  ('deficit-deadlift', 'Deficit Deadlift', 'lower-body', 'hinge', 'barbell', 'advanced',
   'Glutes/Hams', '{glutes,hamstrings,quads}', '{lower_back,traps,adductors}', '{forearms,lats,abs}',
   'Sæt dig ned til stangen, spænd ryggen, og pres gulvet væk med benene.', $ex$["Stå på en vægtskive med stangen over midten af foden.","Bøj dig ned til stangen med brystet oppe og ryggen flad.","Træk slækket ud af stangen, før den forlader gulvet.","Pres gulvet væk med benene, og hold stangen tæt på skinnebenene.","Lad hofte og skuldre stige i samme tempo.","Stræk hoften helt ud i toppen uden at læne dig bagover."]$ex$, $ex$[{"title":"Hoften skyder op først","body":"Benene strækker, før stangen flytter sig, og lænden må løfte resten. Hold brystet oppe og pres med benene, til stangen passerer knæene."},{"title":"Rund ryg i startpositionen","body":"Den dybere start kræver mere mobilitet, end mange har. Sænk forhøjningen, til du kan sætte ryggen flad, før du trækker."},{"title":"For høj forhøjning","body":"Mere er ikke bedre. 2 til 5 cm er nok til at gøre starten tungere uden at ødelægge positionen."}]$ex$,
   'Den længere bevægelse gør starten fra gulvet tungere og tvinger benene til at arbejde mere. Bruges til at styrke det første stykke af et almindeligt dødløft.', 'Stå på en vægtskive eller lav platform (2 til 5 cm) med fødderne i hoftebredde og stangen over midtfoden. Grib lige uden for benene, sænk hoften, og spænd lats og mave.', 'Tilføj en pause lige over gulvet, eller sænk på tre til fire sekunder.', 'Almindeligt dødløft fra gulvet, eller dødløft med trap bar.',
   1765, false),
  ('deficit-dumbbell-romanian-deadlift', 'Deficit Dumbbell Romanian Deadlift', 'lower-body', 'hinge', 'dumbbell', 'intermediate',
   'Hamstrings', '{hamstrings,glutes}', '{lower_back,adductors}', '{forearms,traps,lats,abs}',
   'Hoften bagud, håndvægtene tæt langs benene, og sænk dybt med flad ryg.', $ex$["Stå på en vægtskive eller lav kasse med en håndvægt i hver hånd.","Skub hoften bagud med let bøjede knæ.","Lad håndvægtene glide tæt langs lår og skinneben.","Sænk, til baglårene er i fuldt stræk, og ryggen stadig er neutral.","Pres hoften frem og ret dig helt op."]$ex$, $ex$[{"title":"Skuldrene falder frem","body":"Håndvægtene trækker skuldrene ned og runder den øvre ryg. Træk skulderbladene let tilbage og hold brystet åbent."},{"title":"Jagter gulvet","body":"Du runder lænden for at nå længere ned. Dybden kommer fra hoften: stop, når den ikke kan skubbes længere bagud."},{"title":"Knæene bøjer for meget","body":"Bevægelsen bliver til en squat, og strækket i baglårene forsvinder. Hold knævinklen næsten fast."}]$ex$,
   'Giver baglår og baller et dybt stræk under belastning uden en tung stang. Håndvægtene er nemme at styre og kræver mindre udstyr end stangvarianten.', 'Stå på en vægtskive eller lav kasse (5 til 10 cm) med fødderne i hoftebredde. Hold en håndvægt i hver hånd foran lårene med skuldrene trukket ned.', 'Skift til deficit barbell Romanian deadlift, sænk på fire sekunder, eller lav øvelsen på ét ben.', 'Romanian deadlift med håndvægte fra gulvniveau, eller forkort bevægelsen til lige under knæene.',
   1765, false),
